<?php session_start();require_once "config/database.php";if(!isset($_SESSION['user_id'])){header('Location: login.php');exit;} $pdo->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?')->execute([$_SESSION['user_id']]);$s=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 50');$s->execute([$_SESSION['user_id']]);$items=$s->fetchAll(PDO::FETCH_ASSOC);?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notifications</title><link rel="stylesheet" href="assets/css/style.css"></head><body><?php $base='';include __DIR__.'/includes/navbar.php';?><div class="container"><h1>Notifications</h1><?php foreach($items as $n):?><div class="notification-card"><strong><?=htmlspecialchars($n['title'])?></strong><p><?=htmlspecialchars($n['message'])?></p><small><?=htmlspecialchars($n['created_at'])?></small><?php if($n['link']):?><br><a href="<?=htmlspecialchars($n['link'])?>">Open</a><?php endif;?></div><?php endforeach;if(!$items):?><p class="muted">No notifications yet.</p><?php endif;?></div></body></html>